values
(null,'guidance','Strategies to Prevent Hospital-onset Staphylococcus aureus Bloodstream Infections in Acute Care Facilities','CDC','https://www.cdc.gov/staphylococcus-aureus/hcp/infection-control/index.html','2025-06','en','review',jsonb_build_object('official',true,'topic','mrsa-screening-decolonization','review_required',true,'phase','4I'),'pending'),
